// How the numbers are figured loads on first open (it carries every rule's
// text); lazyWithRetry reloads once if a deploy removed the chunk.
const HowFigured = lazyWithRetry(() => import('../HowFigured'));

// One collapsible subsection inside a guide section.
//
// Added 2026-08-20 to fix a real readability failure: the Plan Settings
// section had grown into two bullets of roughly 7,000 and 12,000 characters
// -- single paragraphs that ran forty-plus lines on screen and covered five
// different sub-tabs each. Nobody reads that. Worse, it had drifted out of
// step with the app: the intro claimed "four sub-tabs" when there are nine,
// and "Assumptions & Risk" was described in two separate bullets.
//
// The structural fix is to mirror the app's own navigation -- one
// subsection per real sub-tab, in the same order the sub-tabs appear -- so
// a reader looking at a screen can find the matching entry by name instead
// of scanning a paragraph for a bolded phrase. Everything is collapsed by
// default, which turns a wall of text into a nine-item table of contents.
//
// Native <details> rather than React state on purpose: it needs no
// controller, it is keyboard accessible and searchable by the browser's own
// find-in-page for free, and it degrades correctly when printed.
function GuideSubsection({ title, summary, children }) {
  return (
    <details
      style={{
        borderRadius: '10px',
        border: '1px solid var(--card-border)',
        background: 'var(--bg-secondary)',
        padding: '2px 0',
      }}
    >
      <summary
        style={{
          cursor: 'pointer',
          padding: '12px 14px',
          listStyle: 'revert',
          color: 'var(--text-primary)',
          fontWeight: 600,
          fontSize: 'var(--fs-body)',
        }}
      >
        {title}
        <span style={{ display: 'block', fontWeight: 400, fontSize: 'var(--fs-xs)', color: 'var(--text-muted)', marginTop: '2px' }}>
          {summary}
        </span>
      </summary>
      <div
        style={{
          padding: '4px 14px 14px',
          display: 'flex',
          flexDirection: 'column',
          gap: '12px',
          lineHeight: 1.65,
        }}
      >
        {children}
      </div>
    </details>
  );
}

